  function allClaims(){let out=[]; claimKeys().forEach(k=>{const arr=read(k,[]); if(Array.isArray(arr)) arr.forEach((x,i)=>out.push(Object.assign({__source:k,__index:i},x||{})))}); const seen=new Set(); return out.filter((x,i)=>{const id=idOf(x,i); const sig=id+'|'+(x.__source||''); if(seen.has(sig))return false; seen.add(sig); return true})}
