  function damages(){let out=[]; const a=read(DAMAGE_KEY,[]); if(Array.isArray(a))out=out.concat(a); ['oj_damage_master_v11_backup','oj_damage_master_log_v11','off_damage_master_log_v11','oceanjet_damage_cases'].forEach(k=>{const v=read(k,null); if(Array.isArray(v))out=out.concat(v); else if(v&&Array.isArray(v.cases))out=out.concat(v.cases)}); const seen=new Set(); return out.filter((x,i)=>{const id=clean(x?.caseId||x?.id||x?.claimId)||('D-'+i); if(seen.has(id))return false; seen.add(id); return true})}
