  function timeline(st){st=String(st||'Submitted').toLowerCase(); const steps=['Submitted','Verified','Processing','Resolved']; const index=st.includes('resolved')||st.includes('closed')?3:st.includes('processing')?2:st.includes('verified')?1:0; return '<div class="oj45-timeline">'+steps.map((x,i)=>'<div class="oj45-lineStep '+(i<index?'done':i===index?'current':'')+'"><b>'+x+'</b><br><small>'+(i<index?'Completed':i===index?'Current step':'Waiting')+'</small></div>').join('')+'</div>'}
